<?php require_once 'includes/admin_common.php';
$q=trim($_GET['q']??'');$role=trim($_GET['role']??'');$class=trim($_GET['class']??'');$login=trim($_GET['login']??'');$lock=trim($_GET['lock']??'');$email=trim($_GET['email']??'');$date=trim($_GET['date']??'');
$where=[];$types='';$params=[]; if($q!==''){$where[]='(name LIKE ? OR username LIKE ? OR email LIKE ? OR role LIKE ? OR class LIKE ?)';$like="%$q%";$types.='sssss';array_push($params,$like,$like,$like,$like,$like);} if($role!==''){$where[]='UPPER(role)=?';$types.='s';$params[]=strtoupper($role);} if($class!==''){$where[]='class=?';$types.='s';$params[]=$class;} if($login!==''){$where[]='is_logged_in=?';$types.='i';$params[]=(int)$login;} if($lock==='locked'){$where[]='lock_until IS NOT NULL AND lock_until>NOW()';} if($lock==='unlocked'){$where[]='(lock_until IS NULL OR lock_until<=NOW())';} if($email==='locked'){$where[]='email_locked=1';} if($email==='open'){$where[]='(email_locked=0 OR email_locked IS NULL)';} if($date!==''){$where[]='DATE(created_at)=?';$types.='s';$params[]=$date;} $sqlWhere=$where?' WHERE '.implode(' AND ',$where):'';
$users=fetch_all('SELECT * FROM ustads'.$sqlWhere.' ORDER BY created_at DESC,id DESC',$types,$params); $classes=fetch_all('SELECT DISTINCT class FROM ustads WHERE class IS NOT NULL AND class<>"" ORDER BY class');
$stats=['total'=>fetch_one('SELECT COUNT(*) c FROM ustads')['c']??0,'admins'=>fetch_one("SELECT COUNT(*) c FROM ustads WHERE UPPER(role)='ADMIN'")['c']??0,'teachers'=>fetch_one("SELECT COUNT(*) c FROM ustads WHERE UPPER(role)<>'ADMIN'")['c']??0,'logged'=>fetch_one('SELECT COUNT(*) c FROM ustads WHERE is_logged_in=1')['c']??0,'locked'=>fetch_one('SELECT COUNT(*) c FROM ustads WHERE lock_until IS NOT NULL AND lock_until>NOW()')['c']??0,'email'=>fetch_one('SELECT COUNT(*) c FROM ustads WHERE email_locked=0 OR email_locked IS NULL')['c']??0,'reset'=>fetch_one('SELECT COUNT(*) c FROM ustads WHERE reset_token IS NOT NULL OR reset_verified=1')['c']??0];
layout_start('Manage Ustads'); ?>
<section class="hero-card mb-4 animate-in"><div class="row align-items-center"><div class="col-lg-8"><nav aria-label="breadcrumb"><ol class="breadcrumb breadcrumb-dark mb-2"><li class="breadcrumb-item text-white-50">Admin</li><li class="breadcrumb-item text-white active">User Management</li></ol></nav><h2 class="display-6 fw-bold mb-2">Enterprise User Management</h2><p class="mb-0 text-white-50">Search, filter, export and securely administer ustad accounts.</p></div><div class="col-lg-4 text-lg-end mt-3 mt-lg-0"><a href="add_ustad.php" class="btn btn-light btn-lg btn-rounded"><i class="bi bi-person-plus me-2"></i>Add User</a></div></div></section>
<div class="row g-3 mb-4"><?php $cards=[['Total Users','total','bi-people','gradient-primary'],['Admins','admins','bi-shield-lock','gradient-dark'],['Teachers','teachers','bi-person-workspace','gradient-info'],['Logged In','logged','bi-wifi','gradient-success'],['Locked','locked','bi-lock','gradient-danger'],['Email Open','email','bi-envelope-check','gradient-warning'],['Reset Pending','reset','bi-arrow-clockwise','gradient-primary']]; foreach($cards as $c): ?><div class="col-6 col-md-4 col-xl-2"><div class="stat-card <?= $c[3] ?>"><div class="d-flex justify-content-between"><div><div class="small opacity-75"><?= e($c[0]) ?></div><h3 class="fw-bold mb-0" data-counter="<?= (int)$stats[$c[1]] ?>">0</h3></div><div class="stat-icon"><i class="bi <?= $c[2] ?>"></i></div></div></div></div><?php endforeach; ?></div>
<form class="filter-card p-3 mb-4"><div class="row g-3"><div class="col-lg-3"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Search name, username, email..."></div><div class="col-md-2"><select class="form-select" name="role"><option value="">All Roles</option><option <?= $role==='ADMIN'?'selected':'' ?>>ADMIN</option><option <?= $role==='TEACHER'?'selected':'' ?>>TEACHER</option></select></div><div class="col-md-2"><select class="form-select" name="class"><option value="">All Classes</option><?php foreach($classes as $cl): ?><option <?= $class===$cl['class']?'selected':'' ?>><?= e($cl['class']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-select" name="login"><option value="">Login Status</option><option value="1" <?= $login==='1'?'selected':'' ?>>Logged In</option><option value="0" <?= $login==='0'?'selected':'' ?>>Logged Out</option></select></div><div class="col-md-2"><select class="form-select" name="lock"><option value="">Lock Status</option><option value="locked" <?= $lock==='locked'?'selected':'' ?>>Locked</option><option value="unlocked" <?= $lock==='unlocked'?'selected':'' ?>>Unlocked</option></select></div><div class="col-md-1 d-grid"><button class="btn btn-primary btn-rounded"><i class="bi bi-funnel"></i></button></div><div class="col-md-2"><select class="form-select" name="email"><option value="">Email Status</option><option value="locked" <?= $email==='locked'?'selected':'' ?>>Locked</option><option value="open" <?= $email==='open'?'selected':'' ?>>Open</option></select></div><div class="col-md-2"><input type="date" class="form-control" name="date" value="<?= e($date) ?>"></div><div class="col-md-3"><a class="btn btn-light btn-rounded" href="manage_ustads.php">Reset Filters</a> <a class="btn btn-outline-primary btn-rounded" href="export_ustads.php?<?= e(http_build_query($_GET+['type'=>'csv'])) ?>">CSV</a> <a class="btn btn-outline-success btn-rounded" href="export_ustads.php?<?= e(http_build_query($_GET+['type'=>'excel'])) ?>">Excel</a></div></div></form>
<div class="table-card p-3"><div class="table-responsive"><table id="ustadsTable" class="table table-hover align-middle"><thead><tr><th><input type="checkbox"></th><th>User</th><th>Role</th><th>Class</th><th>Status</th><th>Security</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><input type="checkbox" name="ids[]" value="<?= (int)$u['id'] ?>"></td><td><div class="d-flex align-items-center gap-2"><span class="avatar-sm"><?= e(strtoupper(substr($u['name'],0,1))) ?></span><div><strong><?= e($u['name']) ?></strong><div class="small text-muted">@<?= e($u['username']) ?> · <?= e($u['email']) ?></div></div></div></td><td><span class="badge badge-soft text-bg-<?= strtoupper($u['role'])==='ADMIN'?'dark':'info' ?>"><?= e($u['role']) ?></span></td><td><?= e($u['class']) ?></td><td><?= !empty($u['is_logged_in'])?'<span class="badge badge-soft text-bg-success">Online</span>':'<span class="badge badge-soft text-bg-secondary">Offline</span>' ?></td><td><?= is_locked($u['lock_until']??null)?'<span class="badge badge-soft text-bg-danger">Locked</span>':'<span class="badge badge-soft text-bg-success">Unlocked</span>' ?> <?= !empty($u['email_locked'])?'<span class="badge badge-soft text-bg-warning">Email Locked</span>':'' ?></td><td><?= e($u['created_at']) ?></td><td><div class="d-flex gap-1"><a class="btn btn-light action-btn" href="view_ustad.php?id=<?= (int)$u['id'] ?>" title="View"><i class="bi bi-eye"></i></a><a class="btn btn-light action-btn" href="edit_ustad.php?id=<?= (int)$u['id'] ?>" title="Edit"><i class="bi bi-pencil"></i></a><button class="btn btn-light action-btn" data-action="unlock" data-id="<?= (int)$u['id'] ?>" title="Unlock"><i class="bi bi-unlock"></i></button><button class="btn btn-light action-btn" data-action="logout" data-id="<?= (int)$u['id'] ?>" title="Logout"><i class="bi bi-box-arrow-right"></i></button><a class="btn btn-danger action-btn" data-confirm-delete href="delete_ustad.php?id=<?= (int)$u['id'] ?>" title="Delete"><i class="bi bi-trash"></i></a></div></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php layout_end();
